# End-to-end smoke test (Playwright for Python). Run the site first: python -m http.server 5501
# Then: pip install playwright && playwright install chromium && python tests/e2e_smoke.py
from playwright.sync_api import sync_playwright
import tempfile
res=[]; errs=[]
def ok(name,cond,extra=""): res.append((name,bool(cond),extra)); print(("PASS " if cond else "FAIL ")+name, extra)
with sync_playwright() as p:
    b=p.chromium.launch()
    ctx=b.new_context(viewport={"width":1440,"height":900}); ctx.route("**/fonts.g*/**",lambda r:r.abort())
    pg=ctx.new_page()
    shots=tempfile.TemporaryDirectory()
    pg.on("pageerror",lambda e:errs.append(str(e)))
    pg.on("console",lambda m:errs.append(m.text) if m.type=="error" and "ERR_FAILED" not in m.text else None)
    pg.goto("http://localhost:5501/"); pg.wait_for_timeout(700)
    pg.evaluate("document.querySelectorAll('img[loading=lazy]').forEach(i=>i.loading='eager')"); pg.wait_for_timeout(500)
    broken=pg.evaluate("[...document.images].filter(i=>!i.complete||i.naturalWidth===0).map(i=>i.getAttribute('src'))")
    ok("all landing images load", not broken, str(broken))
    # --- nav links
    for sec in ["about","features","how","quests","rewards","faq","signin","home"]:
        pg.click(f'#publicNav a[href="#{sec}"]'); pg.wait_for_timeout(1400 if sec=="home" else 900)
        top=pg.evaluate(f"document.getElementById('{sec}').getBoundingClientRect().top")
        act=pg.evaluate("document.querySelector('#publicNav a.active')?.dataset.spy")
        ok(f"nav #{sec} lands below sticky bar",  -2<=top<=90 or sec=="signin" , f"top={top:.0f}")
        ok(f"nav #{sec} active highlight", act==sec, f"active={act}")
    sticky=pg.evaluate("document.getElementById('publicHeader').getBoundingClientRect().top")
    ok("navbar sticky while scrolled", sticky==0)
    pg.click('a:has-text("Play Now")'); pg.wait_for_timeout(800)
    # --- login validation
    pg.fill("#loginUsername","a"); pg.click("#loginSubmit")
    ok("short name rejected w/ message", pg.is_visible("#loginError") and "at least 2" in pg.inner_text("#loginError"))
    pg.fill("#loginUsername","Ke<y>"); pg.click("#loginSubmit")
    ok("illegal chars rejected", pg.is_visible("#loginError"))
    pg.fill("#loginUsername","Kaelen"); pg.click("#loginSubmit"); pg.wait_for_timeout(700)
    ok("login opens dashboard", pg.is_visible("#app") and not pg.is_visible("#publicHeader") and pg.url.endswith("#/dashboard"))
    ok("dashboard shows name", pg.inner_text("#dashboardPlayer")=="Kaelen")
    # --- quest completion
    ok("start XP 0", pg.inner_text("#dashboardTotalXp")=="0")
    progression=pg.evaluate("""async () => {
      const { xpRequiredForLevel, awardXp, levelTheme, LEVEL_THEMES, totalXpForProgression, progressionFromTotalXp } = await import('/js/player.js');
      const sample={level:1,xp:0,totalXp:0}; awardXp(sample,1000);
      const totalXp=totalXpForProgression(5,197);
      return {required:[1,2,3,4].map(xpRequiredForLevel), sample, totalXp, roundTrip:progressionFromTotalXp(totalXp), themes:LEVEL_THEMES.map(theme=>theme.key), first:levelTheme(1).key,last:levelTheme(99).key};
    }""")
    ok("progressive XP formula", progression["required"]==[100,283,520,800],str(progression["required"]))
    ok("large reward handles multiple level-ups and overflow", progression["sample"]=={"level":4,"xp":97,"totalXp":1000},str(progression["sample"]))
    ok("progression converts to lifetime XP with the shared curve", progression["totalXp"]==1900 and progression["roundTrip"]=={"level":5,"xp":197},str(progression))
    ok("level theme palette follows requested sequence", progression["themes"]==["cyan","teal","blue","indigo","violet","magenta","pink","orange","red"] and progression["first"]=="cyan" and progression["last"]=="red")
    ok("level 1 dashboard starts cyan", pg.evaluate("document.documentElement.dataset.levelTheme")=="cyan")
    pg.click('a[data-route="quests"]'); pg.wait_for_timeout(300)
    ok("12 quest cards", pg.locator("#questGrid .quest-card").count()==12)
    pg.locator('[data-quest="1"]').click(); pg.wait_for_timeout(300)
    ok("reward modal centered shows +80 XP", pg.is_visible("#modal") and "+80 XP" in pg.inner_text("#modalContent"))
    ok("modal lists first-quest badge", "First Blood" in pg.inner_text("#modalContent"))
    pg.screenshot(path=f"{shots.name}/app_modal.png")
    pg.click(".reward-continue"); pg.wait_for_timeout(200)
    ok("completed quest moved to separate lower section", pg.locator("#questGrid .quest-card").count()==11 and pg.locator("#completedQuestGrid .quest-card").count()==1 and pg.locator("#completedQuestGrid [data-quest='1']").is_disabled() and pg.inner_text("#completedQuestCount")=="1")
    below=pg.evaluate("document.querySelector('#questGrid').compareDocumentPosition(document.querySelector('#completedQuestGrid')) & Node.DOCUMENT_POSITION_FOLLOWING")
    ok("completed section follows active list", below)
    pg.locator("#completedQuestGrid [data-reopen='1']").click(); pg.wait_for_timeout(150)
    ok("reopened quest returns to active list", pg.locator("#questGrid [data-quest='1']").count()==1 and pg.locator("#completedQuestGrid [data-quest='1']").count()==0)
    pg.locator("#questGrid [data-quest='1']").click(); pg.wait_for_timeout(200)
    ok("reopened quest cannot earn XP twice", "+0 XP" in pg.inner_text("#modalContent") and pg.evaluate("JSON.parse(localStorage.getItem('aion-semester-player')).totalXp")==80)
    pg.click(".reward-continue")
    # double-grant attempts: force-click disabled via JS & second tab
    pg.evaluate("document.querySelector('[data-quest=\"1\"]').disabled=false; document.querySelector('[data-quest=\"1\"]').click()"); pg.wait_for_timeout(200)
    xp=pg.evaluate("JSON.parse(localStorage.getItem('aion-semester-player')).totalXp")
    ok("no double XP from forced re-click", xp==80, f"xp={xp}")
    pg2=ctx.new_page(); pg2.goto("http://localhost:5501/#/quests"); pg2.wait_for_timeout(600)
    ok("2nd tab sees quest already done", pg2.locator("#completedQuestGrid [data-quest='1']").is_disabled())
    # stale tab test: tab1 loaded state before tab2 completes quest 3
    pg.reload(); pg.wait_for_timeout(500); pg.goto("http://localhost:5501/#/quests"); pg.wait_for_timeout(400)
    pg2.locator('[data-quest="3"]').click(); pg2.wait_for_timeout(300)
    pg.locator('[data-quest="3"]').click() if not pg.locator('[data-quest="3"]').is_disabled() else None
    pg.wait_for_timeout(300)
    xp=pg.evaluate("JSON.parse(localStorage.getItem('aion-semester-player')).totalXp")
    ok("stale-tab click cannot double-grant", xp==130, f"xp={xp}")
    ok("dashboard daily completion count is live", pg.inner_text("#qsTodayText")=="Today: 2 quests completed")
    pg2.close()
    # --- daily drop
    pg.click('a[data-route="dashboard"]'); pg.wait_for_timeout(300)
    pg.click("#dailyRewardButton"); pg.wait_for_timeout(300)
    ok("daily drop modal +50", "+50 XP" in pg.inner_text("#modalContent")); pg.click(".reward-continue")
    ok("daily button disabled after claim", pg.is_disabled("#dailyRewardButton"))
    xp=pg.evaluate("JSON.parse(localStorage.getItem('aion-semester-player')).totalXp"); ok("daily granted once", xp==180, f"xp={xp}")
    ok("recent activity lists entries", pg.locator("#dashboardActivity .activity-row").count()==3)
    pg.screenshot(path=f"{shots.name}/app_dashboard.png",full_page=True)
    # --- create custom quest + validation
    pg.click('a[data-route="quests"]'); pg.click("#createQuestButton")
    pg.fill("#newTitle","ab"); pg.fill("#newDescription","Write the report"); pg.click("#createForm button[type=submit]")
    ok("quest form shows inline error", pg.is_visible("#questFormError"))
    pg.fill("#newTitle","Write report"); pg.fill("#newXp","9999"); pg.click("#createForm button[type=submit]")
    ok("XP out of range rejected", "XP reward" in pg.inner_text("#questFormError"))
    pg.fill("#newXp","500"); pg.fill("#newDueDate","2020-01-01"); pg.click("#createForm button[type=submit]")
    ok("past due date rejected", "past" in pg.inner_text("#questFormError"))
    pg.fill("#newDueDate",""); pg.select_option("#newPriority","High"); pg.fill("#newObjectives","Read the report\nWrite the summary"); pg.click("#createForm button[type=submit]"); pg.wait_for_timeout(300)
    ok("custom quest added", pg.locator(".quest-card:has-text('Write report')").count()==1)
    pg.select_option("#questPriority","High"); ok("priority filter", pg.locator("#questGrid .quest-card").count()==1); pg.select_option("#questPriority","All")
    pg.locator('.quest-card:has-text("Write report") [data-objective-index="0"]').check()
    ok("objectives gate completion", pg.locator('.quest-card:has-text("Write report") [data-quest]').is_disabled())
    pg.locator('.quest-card:has-text("Write report") [data-edit]').click(); pg.fill("#newTitle","Write final report"); pg.click("#createForm button[type=submit]"); pg.wait_for_timeout(200)
    ok("quest edited with objective progress preserved", pg.locator(".quest-card:has-text('Write final report')").count()==1 and pg.locator('.quest-card:has-text("Write final report") [data-objective-index="0"]').is_checked())
    pg.locator('.quest-card:has-text("Write final report") [data-objective-index="1"]').check()
    pg.select_option("#questSort","priority")
    ok("priority sorting", "High priority" in pg.locator("#questGrid .quest-card").first.inner_text())
    pg.select_option("#questSort","newest")
    pg.locator('.quest-card:has-text("Write final report") [data-quest]').click(); pg.wait_for_timeout(250)
    ok("custom quest completed for configured XP", "+500 XP" in pg.inner_text("#modalContent") and pg.locator("#completedQuestGrid .quest-card:has-text('Write final report')").count()==1)
    pg.click(".reward-continue")
    pg.reload(); pg.wait_for_timeout(500); pg.goto("http://localhost:5501/#/quests"); pg.wait_for_timeout(300)
    ok("objective completion persists after refresh", pg.locator("#completedQuestGrid .quest-card:has-text('Write final report') [data-objective-index='0']").is_checked())
    pg.locator("#completedQuestGrid .quest-card:has-text('Write final report') [data-reopen]").click()
    pg.locator("#questGrid .quest-card:has-text('Write final report') [data-quest]").click(); pg.wait_for_timeout(200)
    ok("reopened custom quest does not repeat XP", "+0 XP" in pg.inner_text("#modalContent") and pg.evaluate("JSON.parse(localStorage.getItem('aion-semester-player')).totalXp")==680)
    pg.click(".reward-continue")
    pg.once("dialog",lambda d:d.accept()); pg.locator('.quest-card:has-text("Write final report") [data-delete]').click(); pg.wait_for_timeout(200)
    ok("quest deleted from the board", pg.locator(".quest-card:has-text('Write final report')").count()==0)
    # generator
    pg.click("#generateQuestButton"); pg.select_option("#generateDifficulty","Hard"); pg.click("#generateForm button[type=submit]"); pg.wait_for_timeout(200)
    pg.click("#previewForm button[type=submit]"); pg.wait_for_timeout(300)
    ok("generated quests added", pg.locator("#questGrid .quest-card").count()+pg.locator("#completedQuestGrid .quest-card").count()==15)
    generated_ids=pg.locator("#questGrid .quest-card").evaluate_all("(cards) => cards.map(card => card.querySelector('[data-quest]')?.dataset.quest).filter(id => Number(id) > 12)")[:3]
    ok("three generated quest ids available",len(generated_ids)==3)
    level_notice=False
    for quest_id in generated_ids:
        pg.locator(f"#questGrid [data-quest='{quest_id}']").click(); pg.wait_for_timeout(100)
        level_notice=level_notice or ("Level " in pg.inner_text("#modalContent") and " reached" in pg.inner_text("#modalContent"))
        pg.click(".reward-continue")
    ok("XP levels up and dashboard updates", pg.locator("#headerLevel").inner_text()=="LV 4" and pg.inner_text("#dashboardLevel")=="4")
    ok("level-up notification is shown",level_notice)
    ok("dashboard progression theme updates after level-ups",pg.evaluate("document.documentElement.dataset.levelTheme")=="indigo")
    # filters
    pg.fill("#questSearch","HTML"); ok("search filters", pg.locator("#questGrid .quest-card").count()==0 and pg.locator("#completedQuestGrid .quest-card").count()==1); pg.fill("#questSearch","")
    pg.select_option("#questStatus","Completed"); ok("status filter completed", pg.locator("#questGrid .quest-card").count()==0 and pg.locator("#completedQuestGrid .quest-card").count()==5); pg.select_option("#questStatus","All")
    pg.fill("#questSearch","zzzz"); ok("empty state", pg.is_visible("#questEmpty")); pg.fill("#questSearch","")
    # other pages
    for r in ["inventory","leaderboard","profile","stats","settings"]:
        pg.click(f'a[data-route="{r}"]'); pg.wait_for_timeout(250); pg.screenshot(path=f"{shots.name}/app_{r}.png",full_page=True)
    pg.click('a[data-route="leaderboard"]'); ok("leaderboard includes player", pg.locator(".leader-row.you").count()==1)
    # settings
    pg.click('a[data-route="settings"]'); pg.fill("#settingsName","X"); pg.click("#settingsForm button[type=submit]")
    ok("settings validation", pg.is_visible("#settingsError"))
    pg.fill("#settingsName","Kaelen the Bold"); pg.select_option("#settingsTheme","sky"); pg.click("#settingsForm button[type=submit]")
    ok("theme applied", pg.evaluate("document.documentElement.dataset.theme")=="sky" and pg.inner_text("#headerName")=="Kaelen the Bold")
    pg.reload(); pg.wait_for_timeout(800)
    saved_xp=pg.evaluate("JSON.parse(localStorage.getItem('aion-semester-player')).totalXp")
    saved_rewards=pg.evaluate("JSON.parse(localStorage.getItem('aion-semester-player')).rewardHistory")
    reward_total=sum(reward["xp"] for reward in saved_rewards)
    actual_accent=pg.evaluate("getComputedStyle(document.documentElement).getPropertyValue('--accent').trim().toLowerCase()")
    ok("persists XP, level, settings and level color after reload", pg.is_visible("#app") and pg.evaluate("document.documentElement.dataset.theme")=="sky" and pg.evaluate("document.documentElement.dataset.levelTheme")=="indigo" and actual_accent in ["#797cff","rgb(121, 124, 255)"] and saved_xp==reward_total==1190 and pg.inner_text("#dashboardLevel")=="4", f"saved_xp={saved_xp}, level={pg.inner_text('#dashboardLevel')}, accent={actual_accent}")
    # --- isolated level demonstration mode
    pg.click('a[data-route="dashboard"]'); pg.wait_for_timeout(200)
    ok("demo card is on dashboard, not settings", pg.locator('.view[data-view="dashboard"] .level-demo').count()==1 and pg.locator('.view[data-view="settings"] .level-demo').count()==0)
    saved_before_demo=pg.evaluate("localStorage.getItem('aion-semester-player')")
    pg.click("#toggleLevelDemo")
    ok("demo mode starts at actual level with indicator", pg.is_visible("#demoControls") and pg.is_visible("#demoIndicator") and pg.inner_text("#demoIndicator")=="DEMO PREVIEW" and pg.input_value("#demoLevel")=="4" and pg.inner_text("#demoThemeName")=="Indigo")
    pg.fill("#demoLevel","1"); pg.press("#demoLevel","Enter")
    ok("demo level selector previews cyan", pg.inner_text("#demoThemeName")=="Cyan" and pg.inner_text("#demoXpRequired")=="100")
    pg.fill("#demoXpAmount","25"); pg.click("#addDemoXp")
    ok("demo XP below threshold updates without leveling", pg.inner_text("#demoLevelValue")=="1" and pg.inner_text("#demoXpValue")=="25" and pg.inner_text("#demoXpRequired")=="100" and pg.locator("#demoXpBar").evaluate("(bar) => parseFloat(bar.style.width)")==25)
    pg.fill("#demoXpAmount","75"); pg.click("#addDemoXp")
    ok("demo XP reaching threshold levels up", pg.inner_text("#demoLevelValue")=="2" and pg.inner_text("#demoXpValue")=="0" and pg.inner_text("#demoXpRequired")=="283" and pg.inner_text("#demoThemeName")=="Teal")
    pg.fill("#demoXpAmount","300"); pg.click("#addDemoXp")
    ok("demo XP overflow carries into the next level", pg.inner_text("#demoLevelValue")=="3" and pg.inner_text("#demoXpValue")=="17" and pg.inner_text("#demoXpRequired")=="520" and pg.inner_text("#demoThemeName")=="Blue")
    pg.fill("#demoXpAmount","1500"); pg.click("#addDemoXp")
    demo_visuals=pg.evaluate("""() => ({
      level: document.querySelector('#demoLevelValue').textContent,
      xp: document.querySelector('#demoXpValue').textContent,
      required: document.querySelector('#demoXpRequired').textContent,
      percent: parseFloat(document.querySelector('#demoXpBar').style.width),
      aria: document.querySelector('#demoXpTrack').getAttribute('aria-valuenow'),
      theme: document.querySelector('#demoThemeName').textContent,
      accent: getComputedStyle(document.querySelector('#demoPreview')).getPropertyValue('--accent').trim()
    })""")
    ok("large simulated XP handles multiple level-ups and updates visuals", demo_visuals["level"]=="5" and demo_visuals["xp"]=="197" and demo_visuals["required"]=="1,118" and abs(demo_visuals["percent"]-197/1118*100)<0.01 and demo_visuals["theme"]=="Violet" and demo_visuals["accent"].lower() in ["#a575ff","rgb(165, 117, 255)"], str(demo_visuals))
    ok("demo progress bar accessibility value updates", demo_visuals["aria"]==str(round(197/1118*100)), str(demo_visuals))
    ok("demo XP remains preview-only before application",pg.evaluate("localStorage.getItem('aion-semester-player')")==saved_before_demo and pg.is_visible("#applyDemoToDashboard"))
    pg.click("#demoLevelDown"); ok("demo level can decrease",pg.inner_text("#demoLevelValue")=="4" and pg.inner_text("#demoXpValue")=="0")
    pg.click("#demoLevelUp"); ok("demo level can increase",pg.inner_text("#demoLevelValue")=="5" and pg.inner_text("#demoThemeName")=="Violet")
    saved_after_demo=pg.evaluate("localStorage.getItem('aion-semester-player')")
    ok("demo mode does not change saved player data or unlock real rewards",saved_before_demo==saved_after_demo)
    pg.click("#toggleLevelDemo")
    ok("exiting demo restores real dashboard state",pg.locator("#demoControls").is_hidden() and pg.is_hidden("#demoIndicator") and pg.input_value("#demoLevel")=="4" and pg.inner_text("#demoXpValue")=="287" and pg.inner_text("#dashboardLevel")=="4" and pg.inner_text("#dashboardXp")=="287" and pg.evaluate("document.documentElement.dataset.levelTheme")=="indigo")
    pg.click("#toggleLevelDemo")
    ok("re-entering demo starts from actual player progress",pg.input_value("#demoLevel")=="4" and pg.inner_text("#demoXpValue")=="287")
    pg.fill("#demoLevel","1"); pg.press("#demoLevel","Enter"); pg.fill("#demoXpAmount","1000"); pg.click("#addDemoXp")
    pg.click("#toggleLevelDemo")
    pg.reload(); pg.wait_for_timeout(500)
    ok("refresh discards demo progress and restores real player",pg.locator("#demoControls").is_hidden() and pg.is_hidden("#demoIndicator") and pg.evaluate("document.documentElement.dataset.levelTheme")=="indigo" and pg.inner_text("#dashboardLevel")=="4" and pg.inner_text("#dashboardXp")=="287" and pg.evaluate("localStorage.getItem('aion-semester-player')")==saved_before_demo)
    # --- confirmed demo progression application
    pg.click("#toggleLevelDemo")
    pg.fill("#demoLevel","1"); pg.press("#demoLevel","Enter"); pg.fill("#demoXpAmount","1900"); pg.click("#addDemoXp")
    pg.wait_for_timeout(100)
    apply_preview=pg.evaluate("({level:document.querySelector('#demoLevelValue').textContent,xp:document.querySelector('#demoXpValue').textContent,required:document.querySelector('#demoXpRequired').textContent})")
    before_apply=pg.evaluate("JSON.parse(localStorage.getItem('aion-semester-player'))")
    pg.once("dialog",lambda d:d.dismiss()); pg.click("#applyDemoToDashboard")
    ok("canceling apply keeps preview and saved progression unchanged",pg.is_visible("#demoControls") and pg.inner_text("#demoLevelValue")==apply_preview["level"] and pg.inner_text("#demoXpValue")==apply_preview["xp"] and pg.evaluate("JSON.parse(localStorage.getItem('aion-semester-player'))")==before_apply)
    pg.once("dialog",lambda d:d.accept()); pg.click("#applyDemoToDashboard"); pg.wait_for_timeout(850)
    after_apply=pg.evaluate("JSON.parse(localStorage.getItem('aion-semester-player'))")
    ok("applying demo updates dashboard progression and theme",pg.locator("#demoControls").is_hidden() and pg.is_hidden("#demoIndicator") and pg.inner_text("#dashboardLevel")=="5" and pg.inner_text("#dashboardLevelBig")=="5" and pg.inner_text("#dashboardXp")=="197" and pg.inner_text("#dashboardXpMax")=="1118" and pg.inner_text("#dashboardTotalXp")=="1,900" and pg.evaluate("document.documentElement.dataset.levelTheme")=="violet" and abs(float(pg.locator("#dashboardXpBar").evaluate("(bar)=>parseFloat(bar.style.width)"))-197/1118*100)<0.01)
    ok("applied saved progression matches the existing XP curve",after_apply["level"]==5 and after_apply["xp"]==197 and after_apply["totalXp"]==1900 and after_apply["progressionVersion"]==2)
    ok("applying progression preserves quests and unrelated player data",all(after_apply.get(key)==value for key,value in before_apply.items() if key not in {"level","xp","totalXp","progressionVersion"}))
    pg.reload(); pg.wait_for_timeout(800)
    persisted_apply=pg.evaluate("JSON.parse(localStorage.getItem('aion-semester-player'))")
    ok("applied progression persists after refresh",pg.inner_text("#dashboardLevel")=="5" and pg.inner_text("#dashboardXp")=="197" and pg.inner_text("#dashboardXpMax")=="1118" and pg.evaluate("document.documentElement.dataset.levelTheme")=="violet" and persisted_apply==after_apply)
    mobile=ctx.new_page(); mobile.set_viewport_size({"width":390,"height":844}); mobile.goto("http://localhost:5501/#/dashboard"); mobile.wait_for_timeout(400)
    mobile_box=mobile.locator('.view[data-view="dashboard"] #toggleLevelDemo').bounding_box()
    ok("dashboard demo remains usable on mobile", mobile_box is not None and mobile_box["x"]>=0 and mobile_box["x"]+mobile_box["width"]<=390 and mobile.locator("#toggleLevelDemo").is_visible())
    mobile.close()
