    pg.click('a[data-route="settings"]'); pg.wait_for_timeout(200)
    pg.once("dialog",lambda d:d.accept()); pg.click("#resetButton"); pg.wait_for_timeout(300)
    ok("reset clears XP", pg.evaluate("JSON.parse(localStorage.getItem('aion-semester-player')).totalXp")==0)
    pg.evaluate("const player=JSON.parse(localStorage.getItem('aion-semester-player')); Object.assign(player,{name:'Legacy',xp:720,totalXp:720,level:1,streak:2,bestStreak:2,completed:[]}); delete player.progressionVersion; localStorage.setItem('aion-semester-player',JSON.stringify(player))")
    pg.reload(); pg.wait_for_timeout(400)
    legacy=pg.evaluate("JSON.parse(localStorage.getItem('aion-semester-player'))")
    ok("existing 720 XP progress is preserved and converted", legacy["totalXp"]==720 and legacy["level"]==3 and legacy["xp"]==337,str({key:legacy.get(key) for key in ["totalXp","level","xp"]}))
    pg.evaluate("const player=JSON.parse(localStorage.getItem('aion-semester-player')); player.completed=[1]; delete player.rewardedQuestIds; localStorage.setItem('aion-semester-player',JSON.stringify(player))")
    pg.reload(); pg.wait_for_timeout(400); pg.goto("http://localhost:5501/#/quests"); pg.wait_for_timeout(250)
    pg.locator("#completedQuestGrid [data-reopen='1']").click(); pg.locator("#questGrid [data-quest='1']").click(); pg.wait_for_timeout(200)
    ok("legacy completed quest migration prevents duplicate XP", "+0 XP" in pg.inner_text("#modalContent") and pg.evaluate("JSON.parse(localStorage.getItem('aion-semester-player')).totalXp")==720)
    pg.click(".reward-continue")
